const seed = Math.floor(Math.random() * 100000);
const structures = [
  { type: 'question', hook: 'What if the version of history you learned in school was carefully cleaned up?' },
  { type: 'story', hook: 'A buried diary sat unread for centuries. The first page alone is enough to ruin your appetite.' },
  { type: 'compare', hook: 'You complain about rent, bosses, and dating apps. Ancient people had worse versions of all three.' },
  { type: 'bizarre', hook: 'This daily habit was normal back then. Today it would get you arrested.' }
];
const topics = [
  'The disgusting truth about Ancient Roman street food, apartments, and plumbing',
  'Victorian medicine: the cures that were scarier than the disease',
  'Medieval peasant life: rent, work, romance, and survival',
  'Ancient Egyptian beauty, pets, and punishments nobody mentions',
  'The weirdest real jobs in history and what they paid',
  'Sparta was not a movie. Daily training, food, and fear',
  'How ancient empires handled toxic bosses, debt, and breakups'
];
const structure = structures[seed % structures.length];
const topic = topics[seed % topics.length];
// Stable, high-quality male neural voices
const voices = ['en-US-GuyNeural','en-GB-RyanNeural','en-US-ChristopherNeural','en-AU-WilliamNeural'];
const voice = voices[Math.floor(seed / 7) % voices.length];

const sceneCount = 36 + (seed % 9); // 36-44 scenes (fits Groq token limits)
const grainIntensity = 2 + (seed % 3);
const speedVariation = (0.97 + (seed % 5) / 100).toFixed(2);
return [{ json: { seed, structure, voice, sceneCount, grainIntensity, speedVariation, topic, groqModel: 'openai/gpt-oss-120b' } }];

const rand = $input.item.json;
const systemPrompt = `You write scripts for YouTube channels like Simple History and Ink Explainer.
Goal: entertainment + retention, NOT a textbook.
STYLE: One camera shot per scene. One idea. One visual. Sound like a clever human telling a wild true story.
Ban: delve, explore, tapestry, fascinating, in this video, let's dive in, robust, groundbreaking.
Use open loops: tease a wild payoff early, delay the answer. Output ONLY valid JSON.`;

const userPrompt = [
  `Topic: ${rand.topic}`,
  `Hook: ${rand.structure.hook}`,
  `Write EXACTLY ${rand.sceneCount} scenes for a 12-16 minute video.`,
  `METADATA:`,
  `- youtube_title: human, curiosity, not Title Case Spam`,
  `- youtube_description: casual + Chapters + pinned comment`,
  `- thumbnail_prompt: ONE extreme close-up emotion + one prop`,
  `- youtube_tags: 10 tags`,
  `EACH SCENE MUST HAVE:`,
  `- narration: 40-65 words. First line hooks. ONE idea only.`,
  `- visual_action: mandatory. Format: "[character] [doing exact action] [emotion] [1 prop]". Must be drawable as a single still.`,
  `- doodle_prompt: Expand visual_action. MUST match narration. Include: Simple History style, thick black ink, white background, single character, exaggerated face, no photorealism.`,
  `- visual_type: "doodle" for 95%+ ; "stock" only real landscape/nature`,
  `JSON: {"youtube_title":"...","youtube_description":"...","thumbnail_prompt":"...","youtube_tags":["..."],"scenes":[{"narration":"...","visual_action":"...","doodle_prompt":"...","visual_type":"doodle","stock_keyword":"..."}]}`
].join('\n');

const groqBody = {
  model: rand.groqModel || 'openai/gpt-oss-120b',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  temperature: 0.8,
  max_tokens: 6500
};
return [{ json: { ...rand, groqBody } }];

const choice = $input.item.json.choices?.[0] || {};
let raw = choice.message?.content || '';

if (!raw || raw.trim().length < 20) {
  throw new Error('Groq returned empty script content. Check token limits.');
}

let cleanRaw = raw.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
const start = cleanRaw.indexOf('{');
const end = cleanRaw.lastIndexOf('}');
if (start !== -1 && end > start) {
  cleanRaw = cleanRaw.slice(start, end + 1);
}

let jsonStr = cleanRaw
  .replace(/\*\*\s*("[^"]+")\s*:\s*\*\*/g, '$1:')
  .replace(/\*\*\s*("[^"]+")\s*\*\*\s*:/g, '$1:')
  .replace(/\*\*\s*([a-zA-Z0-9_-]+)\s*\*\*\s*:/g, '"$1":')
  .replace(/:\s*\*\*\s*("[^"]*")\s*\*\*/g, ': $1')
  .replace(/:\s*\*\*\s*([a-zA-Z0-9_]+)\s*\*\*/g, ': "$1"')
  .replace(/\*\*/g, '')
  .replace(/,\s*([}\]])/g, '$1');

let data;
try { data = JSON.parse(jsonStr); } catch (e) {
  throw new Error('Groq JSON parse failed: ' + e.message);
}

const scenes = data.scenes.map((s, i) => ({
  json: {
    index: i,
    narration: (s.narration || '').trim(),
    visual_type: s.visual_type === 'stock' ? 'stock' : 'doodle',
    visual_action: s.visual_action || s.doodle_prompt || 'expressive historical person',
    stock_keyword: s.stock_keyword || 'ancient history',
    youtube_title: data.youtube_title || 'History is wild',
    youtube_description: data.youtube_description || '',
    youtube_tags: Array.isArray(data.youtube_tags) ? data.youtube_tags.join(', ') : (data.youtube_tags || ''),
    thumbnail_prompt: data.thumbnail_prompt || 'shocked face history'
  }
})).filter(s => s.json.narration.length > 15);
return scenes;

