const topic = $('Randomization').first().json.topic;
const groqModel = $('Randomization').first().json.groqModel || 'openai/gpt-oss-120b';
const systemPrompt = 'You write viral YouTube Shorts. JSON only.';
const userPrompt = [
  'Create 3 Shorts about: ' + topic,
  'Each short: exactly 5 scenes, narration 10-15 words max.',
  'visual_action: format "[character] [action] [emotion]".',
  'short_title + short_desc (1 line + hashtags).',
  'JSON: {"shorts":[{"short_title":"...","short_desc":"...","scenes":[{"narration":"...","visual_action":"..."}]}]}'
].join('\n');
return [{ json: { groqBody: { model: groqModel, messages: [{role:'system',content:systemPrompt},{role:'user',content:userPrompt}], temperature: 0.9, max_tokens: 4000 } } }];

const raw = $input.item.json.choices?.[0]?.message?.content || '';
const clean = raw.replace(/```json\s*/gi,'').replace(/```/g,'').trim();
const match = clean.match(/\{[\s\S]*\}/);
if (!match) throw new Error('No JSON found in Shorts response');
let jsonStr = match[0]
  .replace(/\*\*\s*("[^"]+")\s*:\s*\*\*/g, '$1:')
  .replace(/\*\*\s*("[^"]+")\s*\*\*\s*:/g, '$1:')
  .replace(/\*\*\s*([a-zA-Z0-9_-]+)\s*\*\*\s*:/g, '"$1":')
  .replace(/:\s*\*\*\s*("[^"]*")\s*\*\*/g, ': $1')
  .replace(/:\s*\*\*\s*([a-zA-Z0-9_]+)\s*\*\*/g, ': "$1"')
  .replace(/\*\*/g, '')
  .replace(/,\s*([}\]])/g, '$1');
let data;
try { data = JSON.parse(jsonStr); } catch (e) {
  throw new Error('Shorts JSON parse failed: ' + e.message);
}
const out = [];
(data.shorts || []).forEach((short, si) => {
  (short.scenes || []).forEach((sc, sci) => {
    out.push({ json: { shortId: si + 1, sceneIndex: sci, narration: sc.narration, visual_action: sc.visual_action || 'historical person', title: short.short_title, desc: short.short_desc } });
  });
});
return out;

const shortsMeta = {};
for (const item of $('Parse Shorts').all()) {
  const j = item.json;
  if (!shortsMeta[j.shortId]) shortsMeta[j.shortId] = j;
}
return [1,2,3].map(i => ({
  json: {
    file: `/home/node/.n8n-files/final_short_${i}.mp4`,
    title: (shortsMeta[i] && shortsMeta[i].title) || `Short ${i}`,
    desc: (shortsMeta[i] && shortsMeta[i].desc) || ''
  }
}));
